import * as zlib from "zlib";

const COMPRESSED_CATALOG = "";

let cachedCatalog: { items: Record<string, string>; equipmentIds: number[] } | null = null;

export function getDecompressedCatalog() {
  if (!cachedCatalog) {
    const buffer = Buffer.from(COMPRESSED_CATALOG, "base64");
    const decompressed = zlib.gunzipSync(buffer);
    cachedCatalog = JSON.parse(decompressed.toString("utf-8"));
  }
  return cachedCatalog;
}

export default function handler(req: any, res: any) {
  res.setHeader("Access-Control-Allow-Origin", "*");
  res.setHeader("Access-Control-Allow-Methods", "GET, OPTIONS");
  res.setHeader("Access-Control-Allow-Headers", "Content-Type");
  res.setHeader("Cache-Control", "public, max-age=3600, s-maxage=86400");

  if (req.method === "OPTIONS") {
    return res.status(200).end();
  }

  try {
    const isDownload = req.url?.includes("download") || req.query?.download;
    const isV2 = req.query?.v === "2" || req.query?.rich === "1" || isDownload;
    const catalog = getDecompressedCatalog();

    if (isDownload) {
      res.setHeader("Content-Disposition", "attachment; filename=items_db.json");
    }

    if (isV2) {
      return res.status(200).json(catalog);
    }

    return res.status(200).json(catalog.items);
  } catch (error: any) {
    return res.status(500).json({ error: "Error al descomprimir diccionario", details: error?.message });
  }
}
